// Extra route and world mechanics are layered onto the existing game systems.
let tunnelLava=[],movingClouds=[],worldMovingPlatforms=[];
function bindPlatformStars(list){for(const p of list)for(const s of stars)if(!s.taken&&s.x>=p.x+20&&s.x<=p.x+p.w-10&&Math.abs(s.y-(p.y-40))<4){s.movingPlatform=p;s.moveOffsetX=s.x-p.x;s.moveOffsetY=s.y-p.y}}
function stepMovingPlatforms(list){for(const p of list){const oldX=p.x,dx=p.moveSpeed*p.moveDir,standing=player.ground&&Math.abs(player.y+player.h-p.y)<3&&player.x+player.w>p.x&&player.x<p.x+p.w;p.x+=dx;if(p.x<p.moveMin||p.x>p.moveMax){p.x=Math.max(p.moveMin,Math.min(p.moveMax,p.x));p.moveDir*=-1}const moved=p.x-oldX;if(standing)player.x+=moved;for(const s of stars)if(s.movingPlatform===p){s.x=p.x+s.moveOffsetX;s.y=p.y+s.moveOffsetY}}}
const loadLevelBase=loadLevel;
loadLevel=function(){loadLevelBase();worldMovingPlatforms=[];const specs=level===0?[[500,58,.85],[1180,66,1]]:level===1?[[1900,72,1],[2710,65,1.1]]:[[3650,52,.8],[4010,82,1.05]];for(const [x,range,speed]of specs){const p=platforms.find(b=>b.x===x);if(p){p.moveMin=x-range;p.moveMax=x+range;p.moveSpeed=speed;p.moveDir=1;worldMovingPlatforms.push(p)}}bindPlatformStars(worldMovingPlatforms);if(level===2){const p=platforms.find(b=>b.x===3230);if(p){p.crumbleBaseY=p.y;p.crumbleTimer=0;p.crumbleReset=0}}};
const enterBonusBase=enterBonus;
enterBonus=function(mode){enterBonusBase(mode);tunnelLava=[];movingClouds=[];if(mode==='cloud'){for(const p of platforms){if(p.x===475||p.x===900){p.moveMin=p.x-34;p.moveMax=p.x+34;p.moveSpeed=p.x===475?.65:.8;p.moveDir=1;movingClouds.push(p)}}bindPlatformStars(movingClouds)}else{const floors=platforms.filter(p=>p.y===560&&p.h===60),layout=[[0,160],[230,190],[490,175],[730,175],[970,190],[1230,190]];floors.forEach((p,i)=>{if(layout[i]){p.x=layout[i][0];p.y=510;p.w=layout[i][1]}});tunnelLava=[[160,230],[420,490],[665,730],[905,970],[1160,1230]];enemies=[{x:325,min:245,max:405,kind:'walker',y:476,w:40,h:34,vx:1.35,dir:1,alive:true,color:'#ce9060'},{x:775,min:745,max:890,kind:'runner',y:476,w:40,h:34,vx:2,dir:1,alive:true,color:'#dc8050'},{x:1020,min:985,max:1140,kind:'charger',y:476,w:40,h:34,vx:2.3,dir:1,alive:true,color:'#e0a34c'}]}};
const updateBase=update;
update=function(){if(state==='playing'){if(routeMode==='cloud')stepMovingPlatforms(movingClouds);else if(routeMode==='main')stepMovingPlatforms(worldMovingPlatforms)}updateBase();if(state==='playing'&&routeMode==='tunnel'){for(const [a,b]of tunnelLava)if(player.x+player.w>a+4&&player.x<b-4&&player.y+player.h>510){hurt(true);break}}if(state==='playing'&&routeMode==='main'&&level===2){const p=platforms.find(b=>b.crumbleBaseY!==undefined);if(p){if(p.crumbleReset>0){p.crumbleReset--;if(!p.crumbleReset){p.y=p.crumbleBaseY;p.crumbleTimer=0}}else if(player.ground&&Math.abs(player.y+player.h-p.crumbleBaseY)<3&&player.x+player.w>p.x&&player.x<p.x+p.w){p.crumbleTimer++;if(p.crumbleTimer===24)p.y=700}else if(p.crumbleTimer>=24){p.crumbleTimer++;if(p.crumbleTimer>95){p.y=p.crumbleBaseY;p.crumbleTimer=0;p.crumbleReset=90}}else p.crumbleTimer=Math.max(0,p.crumbleTimer-2)}}};
const drawBase=draw;
draw=function(){drawBase();if(routeMode==='tunnel'&&tunnelLava.length){c.save();c.translate(-camera,0);for(const [a,b]of tunnelLava){const g=c.createLinearGradient(0,480,0,H);g.addColorStop(0,'#ff9c3d');g.addColorStop(.18,'#e64d32');g.addColorStop(1,'#712d37');c.fillStyle=g;c.fillRect(a,510,b-a,H-510);for(let x=a;x<b;x+=18){const flicker=Math.sin(frame*.17+x*.13),h=19+flicker*6;c.beginPath();c.moveTo(x,510);c.quadraticCurveTo(x-2,498,x+7,503-h);c.quadraticCurveTo(x+16,495,x+18,510);c.closePath();c.fillStyle='#ff7434';c.fill();c.beginPath();c.moveTo(x+5,509);c.quadraticCurveTo(x+7,501,x+10,508-h*.48);c.quadraticCurveTo(x+15,502,x+15,509);c.closePath();c.fillStyle='#ffd45e';c.fill()}}c.restore()}if(routeMode==='main'&&level===2){const p=platforms.find(b=>b.crumbleBaseY!==undefined&&b.y<600);if(p&&p.crumbleTimer>0){c.save();c.translate(-camera,0);c.strokeStyle=p.crumbleTimer>15?'#705b49':'#c77957';c.lineWidth=2;c.beginPath();c.moveTo(p.x+35,p.y+2);c.lineTo(p.x+45,p.y+10);c.lineTo(p.x+54,p.y+3);c.moveTo(p.x+92,p.y+2);c.lineTo(p.x+101,p.y+11);c.lineTo(p.x+111,p.y+3);c.stroke();c.restore()}}};
const paintedScene=draw;draw=function(){paintedScene();storyEdges()};
function loop(t){if(!last)last=t;acc+=Math.min(t-last,100);last=t;while(acc>=1000/60){update();acc-=1000/60}draw();requestAnimationFrame(loop)}
window.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Space','KeyX','KeyS'].includes(e.code))e.preventDefault();keys[e.code]=true;if(e.repeat)return;if(e.code==='Enter')start();if(e.code==='KeyP'||e.code==='Escape')pause();if(e.code==='KeyX')doAttack();if(e.code==='ArrowDown')tryEnterTunnel();if(e.code==='KeyS')tryEnterTunnel()});window.addEventListener('keyup',e=>keys[e.code]=false);window.addEventListener('blur',()=>{Object.keys(keys).forEach(k=>keys[k]=false);if(state==='playing')pause()});$('play').onclick=start;$('pause').onclick=pause;$('restart').onclick=()=>{score=0;health=3;loadLevel();state='paused';start()};$('sound').onclick=()=>{muted=!muted;$('sound').textContent=muted?'♪':'♫';$('sound').title=muted?'เปิดเสียง':'ปิดเสียง';tone(600)};for(const b of document.querySelectorAll('[data-key]')){b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys[b.dataset.key]=true;if(b.dataset.key==='KeyX')doAttack();if(b.dataset.key==='ArrowDown')tryEnterTunnel()});for(const name of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(name,()=>keys[b.dataset.key]=false)}loadLevel();requestAnimationFrame(loop);

$('fullscreen').onclick=()=>{const shell=document.querySelector('.game-shell');if(document.fullscreenElement)document.exitFullscreen?.();else shell.requestFullscreen?.()};
